SELECT event_date_utc, campaign_id_string, campaign_country, SUM(viewable_impressions) AS viewable_impressions, SUM(measurable_impressions) AS measurable_impressions, SUM(unmeasurable_viewable_impressions) AS unmeasurable_viewable_impressions, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM dsp_views GROUP BY event_date_utc, campaign_id_string, campaign_country
